import java.util.HashSet;
import java.util.Set;

public class Conjuntos {
  public static void main(String[] args) {
      Set<Integer> s1 = new HashSet<>(java.util.Arrays.asList(1, 2, 3, 4));
      Set<Integer> s2 = new HashSet<>(java.util.Arrays.asList(3, 4, 5, 6));

      // La intersección (retainAll) modifica el Set original en Java (Mutabilidad):
      s1.retainAll(s2);

      System.out.println(s1); // [3, 4]
  }
}
